"""Grouped selection, explicit ungrouping, compact Layers/Properties and long lines."""
import base64,json,os
from pathlib import Path
from playwright.sync_api import sync_playwright
BASE=os.environ.get('META_STATIC_URL','http://127.0.0.1:8770/_site/')
def address(state):return BASE.split('#')[0]+'#look=v1.'+base64.urlsafe_b64encode(json.dumps(state).encode()).decode().rstrip('=')
with sync_playwright() as p:
 b=p.chromium.launch(channel='chrome',headless=True);page=b.new_page(viewport={'width':1600,'height':1100});errors=[];page.on('pageerror',lambda e:errors.append(str(e)))
 page.goto(address({'variant':1,'paused':True,'offset':3}));page.wait_for_function('window.METAStudio && document.querySelector("#author-element option[value=preset-main]")')
 page.locator('.author-row-select[data-element-id="preset-main"]').click();front=next(f for f in page.frames if 'view=front' in f.url)
 point=front.evaluate('''()=>{for(let y=innerHeight*.1;y<innerHeight*.8;y+=4)for(let x=innerWidth*.5;x<innerWidth*.98;x+=4){const hit=window.META.pickElement(x,y);if(hit?.id==="preset-main")return {x,y};}return null;}''');assert point,'A visible group surface must pick the whole group'
 page.locator('.author-disclosure[data-element-id="preset-main"]').click();assert page.locator('.author-delete[data-element-id="preset-main-part-3"]').is_disabled();page.locator('.author-row-select[data-element-id="preset-main-part-3"]').click();assert page.evaluate('window.METAStudio.state.activeElement')=='preset-main'
 assert page.locator('#author-element option[value="preset-main-part-3"]').count()==0
 page.locator('#group-element').click();page.wait_for_function('!!document.querySelector("#author-element option[value=preset-main-part-3]")');page.locator('.author-row-select[data-element-id="preset-main-part-3"]').click();page.keyboard.press('Delete');page.wait_for_function('!document.querySelector(".author-element-row[data-element-id=preset-main-part-3]")');page.keyboard.press('Control+z');page.wait_for_function('!!document.querySelector(".author-element-row[data-element-id=preset-main-part-3]")')
 page.locator('.author-row-select[data-element-id="preset-main"]').click();page.locator('#group-element').click();assert page.locator('.author-delete[data-element-id="preset-main-part-3"]').is_disabled();page.keyboard.press('Control+z');assert page.locator('.author-delete[data-element-id="preset-main-part-3"]').is_enabled()
 print('PASS Groups protect parts, explicit Ungroup enables part CRUD, Regroup and Undo restore the editing boundary',flush=True)
 layers=page.locator('.author-layers').bounding_box();props=page.locator('.author-properties').bounding_box();assert props['x']>=layers['x']+layers['width']-1;assert abs(props['y']-layers['y'])<2
 row=page.locator('.author-element-row[data-element-id="preset-main"]');assert row.bounding_box()['height']<=46
 page.set_viewport_size({'width':1600,'height':1500});page.evaluate('()=>new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)))');page.evaluate('()=>window.scrollBy(0,document.querySelector("#authoring-controls").getBoundingClientRect().top-document.querySelector(".preview-room").getBoundingClientRect().bottom-12)');page.locator('#authoring-controls').screenshot(path=str(Path(__file__).resolve().parent/'previews/qa-group-editor.png'));page.set_viewport_size({'width':1600,'height':1100})
 page.goto(address({'variant':5,'paused':True,'offset':3}));page.wait_for_function('window.METAStudio && document.querySelector("#author-element option[value=preset-logo-front]")');page.locator('#element-search').fill('long');ribbon=page.locator('.author-row-select').first;assert page.locator('.author-row-select').count()>=2;ribbon.click();lineid=page.evaluate('window.METAStudio.state.activeElement');assert 'connecting-ribbon' in lineid
 front=next(f for f in page.frames if 'view=front' in f.url);front.locator('.element-handle[data-element-id="'+lineid+'"]').wait_for(state='visible');page.locator('#author-y').fill('72');page.locator('#author-size').fill('0.8');assert page.evaluate('(id)=>window.METAStudio.state.authored[5].edits[id].y',lineid)==72
 page.locator('#copy-look-link').click();fresh=b.new_context();restored=fresh.new_page();restored.goto(page.url);restored.wait_for_function('window.METAStudio');assert restored.evaluate('(id)=>window.METAStudio.state.authored[5].edits[id].y',lineid)==72;fresh.close()
 page.set_viewport_size({'width':390,'height':844});page.wait_for_function('document.documentElement.scrollWidth<=innerWidth+1');assert page.locator('.author-properties').bounding_box()['y']>=page.locator('.author-layers').bounding_box()['y'];assert not errors,errors
 print('PASS Compact two-pane editor, editable long lines, saved URLs and mobile layout',flush=True)
 stale=b.new_context(viewport={'width':1600,'height':1100});stale.add_init_script('if(window===top)localStorage.setItem("gsmv-interview-walls-v1",'+json.dumps(json.dumps({'variant':1,'paused':True,'offset':3,'activeElement':'preset-main-part-3','editElements':True}))+')');old=stale.new_page();old.goto(BASE.split('#')[0]);old.wait_for_function('window.METAStudio');wall=next(f for f in old.frames if 'view=front' in f.url);wall.locator('.element-handle[data-element-id="preset-main"]').wait_for(state='visible');box=wall.locator('.element-handle-label').bounding_box();old.mouse.move(box['x']+8,box['y']+5);old.mouse.down();old.mouse.move(box['x']+28,box['y']+13,steps=4);old.mouse.up();old.wait_for_function('!!window.METAStudio.state.authored[1]?.edits["preset-main"]?.x');assert old.evaluate('window.METAStudio.state.activeElement')=='preset-main';stale.close()
 print('PASS A legacy selected leaf draws and moves the protected group on the first gesture',flush=True);b.close()
